<?php $title='Cashier Terminal'; include APPPATH.'Views/layout/header.php'; ?>
<div class="terminal"><section class="catalog"><div class="catalog-head"><div><h2>Product catalog</h2><p>Choose one item to start a sale.</p></div><span class="count"><?= count($products) ?> products</span></div><div class="search-wrap"><span>⌕</span><input id="search" type="search" placeholder="Search products by name..." aria-label="Search products"></div><div class="product-grid" id="product-grid">
<?php foreach($products as $product): ?><button type="button" class="product-card" data-name="<?= esc(mb_strtolower($product['name']),'attr') ?>" data-id="<?= esc($product['id']) ?>" data-label="<?= esc($product['name'],'attr') ?>" data-image="<?= esc(base_url($product['image'] ?: 'assets/food-placeholder.svg'),'attr') ?>" data-price="<?= esc($product['price']) ?>" data-stock="<?= esc($product['stock_quantity']) ?>" <?= $product['stock_quantity']<1?'disabled':'' ?>><div class="product-image"><img src="<?= esc(base_url($product['image'] ?: 'assets/food-placeholder.svg')) ?>" alt=""><span class="stock-badge <?= $product['stock_quantity']<1?'soldout':'' ?>"><?= $product['stock_quantity']<1?'Sold out':esc($product['stock_quantity']).' in stock' ?></span></div><div class="product-info"><strong><?= esc($product['name']) ?></strong><span>₱<?= number_format((float)$product['price'],2) ?></span></div><div class="add-label"><?= $product['stock_quantity']<1?'Unavailable':'Select item →' ?></div></button><?php endforeach ?>
</div><p id="no-results" class="empty" hidden>No products match your search.</p></section>
<aside class="checkout"><div class="checkout-head"><span class="eyebrow">CURRENT SALE</span><h2>Checkout</h2><p>One product per transaction</p></div><form action="<?= site_url('sales') ?>" method="post" id="sale-form"><?= csrf_field() ?><input type="hidden" name="product_id" id="product-id"><div id="selection" class="selection-empty"><span>▤</span><strong>No product selected</strong><p>Choose an item from the catalog to begin.</p></div><div class="checkout-fields"><label>Quantity<input type="number" name="quantity" id="quantity" min="1" step="1" value="1" required></label><label>Customer <small>Optional</small><select name="customer_id"><option value="">Walk-in Customer</option><?php foreach($customers as $customer): ?><option value="<?= esc($customer['id']) ?>"><?= esc($customer['full_name']) ?></option><?php endforeach ?></select></label></div><div class="total-row"><span>Total</span><strong id="total">₱0.00</strong></div><p class="server-note">Final amount and stock are verified when you record the sale.</p><button class="btn primary full" id="record" disabled>Record Sale →</button></form></aside></div>
<script>
const cards=[...document.querySelectorAll('.product-card')], search=document.getElementById('search'), qty=document.getElementById('quantity'), total=document.getElementById('total'), selected=document.getElementById('selection'), record=document.getElementById('record'); let price=0,stock=0;
function update(){let n=Number(qty.value);total.textContent='₱'+(Number.isInteger(n)&&n>0?price*n:0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});record.disabled=!document.getElementById('product-id').value||!Number.isInteger(n)||n<1||n>stock}
cards.forEach(card=>card.addEventListener('click',()=>{cards.forEach(c=>c.classList.remove('selected'));card.classList.add('selected');document.getElementById('product-id').value=card.dataset.id;price=Number(card.dataset.price);stock=Number(card.dataset.stock);qty.max=stock;qty.value=1;selected.className='selection-picked';selected.innerHTML='<img class="picked-image" alt=""><div class="picked-copy"><small>SELECTED PRODUCT</small><strong></strong><span class="picked-detail"></span></div>';selected.querySelector('.picked-image').src=card.dataset.image;selected.querySelector('strong').textContent=card.dataset.label;selected.querySelector('.picked-detail').textContent='₱'+price.toFixed(2)+' each · '+stock+' available';update()}));
search.addEventListener('input',()=>{let visible=0;cards.forEach(c=>{let show=c.dataset.name.includes(search.value.trim().toLocaleLowerCase());c.hidden=!show;if(show)visible++});document.getElementById('no-results').hidden=visible>0});qty.addEventListener('input',update);
</script>
<?php include APPPATH.'Views/layout/footer.php'; ?>
